      setCodexSessionId(sessionIds.codexSessionId);
      if (!chatId) return;
      const updated = chatListRef.current.map((chatMeta) =>
        chatMeta.id === chatId
          ? {
              ...chatMeta,
              claudeSessionId: sessionIds.claudeSessionId,
              codexSessionId: sessionIds.codexSessionId,
            }
          : chatMeta
